    v12 = (uint8_t)v44;
    v14 = kstr(21);
    GC_POINT();
    sb_u64(&rt_sb, v8);
    v15 = sb_take();
    GC_POINT();
    v16 = str_cat(v14, v15);
    v17 = kstr(22);
    GC_POINT();
    v18 = str_cat(v16, v17);
    GC_POINT();
    sb_u64(&rt_sb, v10);
    v19 = sb_take();
    GC_POINT();
    v20 = str_cat(v18, v19);
    GC_POINT();
    v22 = str_cat(v20, v17);
